'use strict';

// MODULES //

var tape = require( 'tape' );
var isSameFloat64Array = require( '@stdlib/assert/is-same-float64array' );
var isAlmostSameValue = require( '@stdlib/assert/is-almost-same-value' );
var Float64Array = require( '@stdlib/array/float64' );
var scalar2ndarray = require( '@stdlib/ndarray/from-scalar' );
var ndarray = require( '@stdlib/ndarray/base/ctor' );
var getData = require( '@stdlib/ndarray/data-buffer' );
var rffti = require( '@stdlib/fft/base/fftpack/ndarray/generic/rffti' );
var rfftf = require( './../lib' );


// FUNCTIONS //

/**
* Returns a one-dimensional ndarray.
*
* @private
* @param {Collection} buffer - underlying data buffer
* @param {NonNegativeInteger} length - number of indexed elements
* @param {integer} stride - stride length
* @param {NonNegativeInteger} offset - index offset
* @returns {ndarray} one-dimensional ndarray
*/
function vector( buffer, length, stride, offset ) {
	return new ndarray( 'float64', buffer, [ length ], [ stride ], offset, 'row-major' );
}


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof rfftf, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 1', function test( t ) {
	t.strictEqual( rfftf.length, 1, 'has expected arity' );
	t.end();
});

tape( 'the function computes the forward discrete Fourier transform of a real-valued one-dimensional ndarray', function test( t ) {
	var expected;
	var wBuf;
	var rBuf;
	var len;
	var N;
	var w;
	var r;
	var v;

	N = 4;
	len = scalar2ndarray( N, {
		'dtype': 'int32'
	});
	rBuf = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );
	r = vector( rBuf, N, 1, 0 );

	wBuf = new Float64Array( ( 2*N ) + 34 );
	w = vector( wBuf, ( 2*N ) + 34, 1, 0 );

	rffti( [ w, len ] );
	v = rfftf( [ r, w ] );

	expected = new Float64Array( [ 10.0, -2.0, 2.0, -2.0 ] );

	t.strictEqual( v, r, 'returns expected value' );
	t.strictEqual( isSameFloat64Array( getData( v ), expected ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided an empty ndarray, the function returns the input ndarray unchanged', function test( t ) {
	var expected;
	var wBuf;
	var rBuf;
	var len;
	var N;
	var w;
	var r;
	var v;

	N = 4;
	len = scalar2ndarray( N, {
		'dtype': 'int32'
	});
	rBuf = new Float64Array( [] );
	r = vector( rBuf, 0, 1, 0 );

	wBuf = new Float64Array( ( 2*N ) + 34 );
	w = vector( wBuf, ( 2*N ) + 34, 1, 0 );

	rffti( [ w, len ] );
	v = rfftf( [ r, w ] );

	expected = new Float64Array( [] );
	t.strictEqual( v, r, 'returns expected value' );
	t.strictEqual( isSameFloat64Array( getData( v ), expected ), true, 'returns expected value' );

	t.end();
});

tape( 'the function supports a one-dimensional ndarray having a non-unit stride', function test( t ) {
	var expected;
	var wBuf;
	var rBuf;
	var ulps;
	var len;
	var N;
	var w;
	var r;
	var v;
	var i;

	N = 4;
	len = scalar2ndarray( N, {
		'dtype': 'int32'
	});
	rBuf = new Float64Array([
		1.0,   // 0
		-999.0,
		2.0,   // 1
		-999.0,
		3.0,   // 2
		-999.0,
		4.0,   // 3
		-999.0
	]);
	r = vector( rBuf, N, 2, 0 );

	wBuf = new Float64Array( ( ( 2*N ) + 34 ) * 2 );
	w = vector( wBuf, ( 2*N ) + 34, 2, 0 );

	rffti( [ w, len ] );
	rfftf( [ r, w ] );

	expected = new Float64Array([
		10.0,  // 0
		-999.0,
		-2.0,  // 1
		-999.0,
		2.0,   // 2
		-999.0,
		-2.0,  // 3
		-999.0
	]);

	ulps = 1;
	for ( i = 0; i < rBuf.length; i++ ) {
		v = rBuf[ i ];
		t.strictEqual( isAlmostSameValue( v, expected[ i ], ulps ), true, 'within ' + ulps + ' ULPs. index: ' + i + '. y: ' + v + '. E: ' + expected[ i ] );
	}

	t.end();
});

tape( 'the function supports a one-dimensional ndarray having a negative stride', function test( t ) {
	var expected;
	var wBuf;
	var rBuf;
	var ulps;
	var len;
	var N;
	var w;
	var r;
	var v;
	var i;

	N = 4;
	len = scalar2ndarray( N, {
		'dtype': 'int32'
	});
	rBuf = new Float64Array([
		4.0,   // 3
		-999.0,
		3.0,   // 2
		-999.0,
		2.0,   // 1
		-999.0,
		1.0    // 0
	]);
	r = vector( rBuf, N, -2, rBuf.length-1 );

	wBuf = new Float64Array( ( 2*N ) + 34 );
	w = vector( wBuf, ( 2*N ) + 34, -1, wBuf.length-1 );

	rffti( [ w, len ] );
	rfftf( [ r, w ] );

	expected = new Float64Array([
		-2.0,  // 3
		-999.0,
		2.0,   // 2
		-999.0,
		-2.0,  // 1
		-999.0,
		10.0   // 0
	]);

	ulps = 1;
	for ( i = 0; i < rBuf.length; i++ ) {
		v = rBuf[ i ];
		t.strictEqual( isAlmostSameValue( v, expected[ i ], ulps ), true, 'within ' + ulps + ' ULPs. index: ' + i + '. y: ' + v + '. E: ' + expected[ i ] );
	}

	t.end();
});

tape( 'the function supports a one-dimensional ndarray having a non-zero offset', function test( t ) {
	var expected;
	var wBuf;
	var rBuf;
	var ulps;
	var len;
	var N;
	var w;
	var r;
	var v;
	var i;

	N = 4;
	len = scalar2ndarray( N, {
		'dtype': 'int32'
	});
	rBuf = new Float64Array([
		-999.0,
		1.0,   // 0
		-999.0,
		2.0,   // 1
		-999.0,
		3.0,   // 2
		-999.0,
		4.0,   // 3
		-999.0
	]);
	r = vector( rBuf, N, 2, 1 );

	wBuf = new Float64Array( 3 + ( ( ( 2*N ) + 34 ) * 2 ) );
	w = vector( wBuf, ( 2*N ) + 34, 2, 3 );

	rffti( [ w, len ] );
	rfftf( [ r, w ] );

	expected = new Float64Array([
		-999.0,
		10.0,  // 0
		-999.0,
		-2.0,  // 1
		-999.0,
		2.0,   // 2
		-999.0,
		-2.0,  // 3
		-999.0
	]);

	ulps = 1;
	for ( i = 0; i < rBuf.length; i++ ) {
		v = rBuf[ i ];
		t.strictEqual( isAlmostSameValue( v, expected[ i ], ulps ), true, 'within ' + ulps + ' ULPs. index: ' + i + '. y: ' + v + '. E: ' + expected[ i ] );
	}

	t.end();
});
